//! The parity check: every TS test at the pinned commit maps to Rust tests, harness scenarios,
//! or a reasoned `n/a`.
//!
//! Inputs:
//! - `parity/ts-tests.json` ([`TsTests`]), generated by `oracle/src/parity/list-tests.mjs`.
//! - `parity/manifest.toml` ([`Manifest`]), maintained by hand: one `[[test]]` table per TS key.
//! - The Rust test names that `cargo nextest list` reports ([`rust_test_names`]).
//! - The harness scenario names, the file stems of `harness/scenarios/*.json` ([`scenario_names`]).
//!
//! [`check`] compares them and returns every [`Problem`].
use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;
use std::{fmt, fs, io};

use serde::Deserialize;

/// The TS test list, `parity/ts-tests.json`.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TsTests {
    /// The TS commit the list comes from.
    pub ts_sha: String,
    /// The number of entries in `tests`.
    pub count: usize,
    /// One entry per TS test, sorted by `key`.
    pub tests: Vec<TsTest>,
}

/// One TS test.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct TsTest {
    /// `<project>|<file>|<title>`: the test's identity in the manifest.
    pub key: String,
    /// The vitest project: `v1`, `v2`, `e2e-http` or `workers`.
    pub project: String,
    /// The test file, relative to the TS repository root, with `/` separators.
    pub file: String,
    /// The describe blocks and the test name, joined by ` > ` (as vitest gives it).
    pub title: String,
}

/// The parity map, `parity/manifest.toml`.
#[derive(Debug, Clone, Default, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Manifest {
    /// The `[[test]]` tables, one per TS key.
    #[serde(default, rename = "test")]
    pub tests: Vec<Entry>,
}

/// One `[[test]]` table of the manifest.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Entry {
    /// The TS test key (see [`TsTest::key`]).
    pub key: String,
    /// How the TS test is covered.
    pub status: Status,
    /// `ported` only: Rust test names (`<binary-id>::<test name>`) and `harness:<scenario>` names.
    #[serde(default)]
    pub rust: Vec<String>,
    /// `n/a` only: `ts-host-only`, `second-pass`, `ruled-divergence:RD-<n>` or
    /// `covered-by-vector:<file>.json`.
    #[serde(default)]
    pub category: Option<String>,
    /// `n/a` only: why the TS test has no Rust counterpart.
    #[serde(default)]
    pub reason: Option<String>,
}

/// The `status` of a manifest entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
pub enum Status {
    /// Not mapped yet. Allowed while the port is in progress; the final gate rejects it.
    #[serde(rename = "todo")]
    Todo,
    /// Covered by the Rust tests and harness scenarios in `rust`.
    #[serde(rename = "ported")]
    Ported,
    /// Has no Rust counterpart, for the `category` and `reason` given.
    #[serde(rename = "n/a")]
    NotApplicable,
}

/// One thing wrong with the parity map.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub enum Problem {
    /// A TS key with no manifest entry, or a `ported` entry with an empty `rust` list.
    Unmapped(String),
    /// A manifest entry whose key is not in the TS test list.
    Stale(String),
    /// A `rust` entry that names a Rust test `cargo nextest list` does not report.
    DanglingRust {
        /// The manifest key.
        key: String,
        /// The missing Rust test name.
        test: String,
    },
    /// A `harness:<scenario>` entry with no `harness/scenarios/<scenario>.json`.
    DanglingScenario {
        /// The manifest key.
        key: String,
        /// The missing scenario name.
        scenario: String,
    },
    /// A `todo` entry under the final gate.
    Todo(String),
    /// An `n/a` entry without a `reason` (or with a blank one).
    MissingReason(String),
    /// An `n/a` entry whose `category` is missing or not one of the allowed forms.
    BadCategory {
        /// The manifest key.
        key: String,
        /// The category as written (empty when missing).
        category: String,
    },
    /// A second manifest entry for the same key.
    Duplicate(String),
    /// A field that the entry's status does not take (`rust` outside `ported`, `category` or
    /// `reason` outside `n/a`).
    Misplaced {
        /// The manifest key.
        key: String,
        /// The field name.
        field: String,
    },
}

impl fmt::Display for Problem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unmapped(key) => write!(
                f,
                "unmapped: {key}: add an entry that maps it to Rust tests or scenarios, or n/a"
            ),
            Self::Stale(key) => write!(f, "stale: {key}: no such TS test; remove the entry"),
            Self::DanglingRust { key, test } => {
                write!(
                    f,
                    "dangling Rust test: {key}: `{test}` is not in `cargo nextest list`"
                )
            }
            Self::DanglingScenario { key, scenario } => write!(
                f,
                "dangling scenario: {key}: harness/scenarios/{scenario}.json does not exist"
            ),
            Self::Todo(key) => write!(f, "todo: {key}"),
            Self::MissingReason(key) => write!(f, "missing reason: {key}: n/a needs a reason"),
            Self::BadCategory { key, category } => write!(
                f,
                "bad category: {key}: {category:?} is not ts-host-only, second-pass, \
                 ruled-divergence:RD-<n> or covered-by-vector:<file>.json"
            ),
            Self::Duplicate(key) => write!(f, "duplicate: {key}: the manifest has it twice"),
            Self::Misplaced { key, field } => write!(
                f,
                "misplaced field: {key}: `{field}` does not belong to this status"
            ),
        }
    }
}

impl TsTests {
    /// Parses `parity/ts-tests.json` and checks that it is consistent: `count` matches, each key
    /// is `<project>|<file>|<title>`, and no key repeats.
    ///
    /// # Errors
    ///
    /// Invalid JSON, a field that is missing or unknown, or an inconsistency.
    pub fn from_json(text: &str) -> Result<Self, String> {
        let list: Self = serde_json::from_str(text).map_err(|e| format!("ts-tests.json: {e}"))?;
        if list.count != list.tests.len() {
            return Err(format!(
                "ts-tests.json: count is {} but there are {} tests",
                list.count,
                list.tests.len()
            ));
        }
        let mut keys = BTreeSet::new();
        for test in &list.tests {
            if test.key != format!("{}|{}|{}", test.project, test.file, test.title) {
                return Err(format!(
                    "ts-tests.json: key {:?} is not <project>|<file>|<title>",
                    test.key
                ));
            }
            if !keys.insert(test.key.as_str()) {
                return Err(format!("ts-tests.json: duplicate key {:?}", test.key));
            }
        }
        Ok(list)
    }
}

impl Manifest {
    /// Parses `parity/manifest.toml`.
    ///
    /// # Errors
    ///
    /// Invalid TOML, a field that is missing or unknown, or an unknown status.
    pub fn from_toml(text: &str) -> Result<Self, String> {
        toml::from_str(text).map_err(|e| format!("manifest.toml: {e}"))
    }
}

/// The Rust test names in the output of
/// `cargo nextest list --workspace --all-features --message-format json`, as
/// `<binary-id>::<test name>` (for example `agentcat-sdk::tokens::tests::rounds_up`).
///
/// The output is `{"rust-suites": {"<binary-id>": {"binary-id": .., "testcases": {"<test name>":
/// {..}}}}}` (other fields are ignored). Ignored tests count: they exist.
///
/// # Errors
///
/// The text is not JSON of that shape.
pub fn rust_test_names(nextest_json: &str) -> Result<BTreeSet<String>, String> {
    #[derive(Deserialize)]
    struct List {
        #[serde(rename = "rust-suites")]
        rust_suites: BTreeMap<String, Suite>,
    }
    #[derive(Deserialize)]
    struct Suite {
        #[serde(rename = "binary-id")]
        binary_id: String,
        testcases: BTreeMap<String, serde_json::Value>,
    }

    let list: List = serde_json::from_str(nextest_json)
        .map_err(|e| format!("cannot read the `cargo nextest list` JSON: {e}"))?;
    let mut names = BTreeSet::new();
    for suite in list.rust_suites.into_values() {
        for test in suite.testcases.into_keys() {
            names.insert(format!("{}::{test}", suite.binary_id));
        }
    }
    Ok(names)
}

/// The scenario names in `dir`: the stems of its `*.json` files. A missing `dir` is an empty set.
///
/// # Errors
///
/// `dir` exists but cannot be read, or a `*.json` file name is not UTF-8.
pub fn scenario_names(dir: &Path) -> Result<BTreeSet<String>, String> {
    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(BTreeSet::new()),
        Err(e) => return Err(format!("cannot read {}: {e}", dir.display())),
    };
    let mut names = BTreeSet::new();
    for entry in entries {
        let path = entry
            .map_err(|e| format!("cannot read {}: {e}", dir.display()))?
            .path();
        if path.extension().is_none_or(|ext| ext != "json") || !path.is_file() {
            continue;
        }
        let stem = path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .ok_or_else(|| format!("{}: the file name is not UTF-8", path.display()))?;
        names.insert(stem.to_owned());
    }
    Ok(names)
}

/// Checks `manifest` against the TS test list, the Rust test names and the scenario names.
/// A `todo` entry is a problem only when `final_gate` is set. Returns the problems sorted.
pub fn check(
    ts: &TsTests,
    manifest: &Manifest,
    rust_tests: &BTreeSet<String>,
    scenarios: &BTreeSet<String>,
    final_gate: bool,
) -> Vec<Problem> {
    let ts_keys: BTreeSet<&str> = ts.tests.iter().map(|t| t.key.as_str()).collect();
    let mut seen = BTreeSet::new();
    let mut problems = Vec::new();
    for entry in &manifest.tests {
        let key = &entry.key;
        if !seen.insert(key.as_str()) {
            problems.push(Problem::Duplicate(key.clone()));
            continue;
        }
        if !ts_keys.contains(key.as_str()) {
            problems.push(Problem::Stale(key.clone()));
            continue;
        }
        check_fields(entry, &mut problems);
        match entry.status {
            Status::Todo => {
                if final_gate {
                    problems.push(Problem::Todo(key.clone()));
                }
            }
            Status::Ported => check_ported(entry, rust_tests, scenarios, &mut problems),
            Status::NotApplicable => check_not_applicable(entry, &mut problems),
        }
    }
    for key in ts_keys.difference(&seen) {
        problems.push(Problem::Unmapped((*key).to_owned()));
    }
    problems.sort();
    problems
}

/// Reports each field that `entry.status` does not take.
fn check_fields(entry: &Entry, problems: &mut Vec<Problem>) {
    let misplaced = [
        (
            "rust",
            entry.status != Status::Ported && !entry.rust.is_empty(),
        ),
        (
            "category",
            entry.status != Status::NotApplicable && entry.category.is_some(),
        ),
        (
            "reason",
            entry.status != Status::NotApplicable && entry.reason.is_some(),
        ),
    ];
    for (field, bad) in misplaced {
        if bad {
            problems.push(Problem::Misplaced {
                key: entry.key.clone(),
                field: field.to_owned(),
            });
        }
    }
}

fn check_ported(
    entry: &Entry,
    rust_tests: &BTreeSet<String>,
    scenarios: &BTreeSet<String>,
    problems: &mut Vec<Problem>,
) {
    if entry.rust.is_empty() {
        problems.push(Problem::Unmapped(entry.key.clone()));
    }
    for name in &entry.rust {
        if let Some(scenario) = name.strip_prefix("harness:") {
            if !scenarios.contains(scenario) {
                problems.push(Problem::DanglingScenario {
                    key: entry.key.clone(),
                    scenario: scenario.to_owned(),
                });
            }
        } else if !rust_tests.contains(name) {
            problems.push(Problem::DanglingRust {
                key: entry.key.clone(),
                test: name.clone(),
            });
        }
    }
}

fn check_not_applicable(entry: &Entry, problems: &mut Vec<Problem>) {
    let category = entry.category.as_deref().unwrap_or_default();
    if !is_valid_category(category) {
        problems.push(Problem::BadCategory {
            key: entry.key.clone(),
            category: category.to_owned(),
        });
    }
    if entry
        .reason
        .as_deref()
        .is_none_or(|reason| reason.trim().is_empty())
    {
        problems.push(Problem::MissingReason(entry.key.clone()));
    }
}

/// `ts-host-only`, `second-pass`, `ruled-divergence:RD-<digits>` or
/// `covered-by-vector:<file>.json` (a file name, not a path).
fn is_valid_category(category: &str) -> bool {
    if let Some(id) = category.strip_prefix("ruled-divergence:RD-") {
        return !id.is_empty() && id.bytes().all(|b| b.is_ascii_digit());
    }
    if let Some(file) = category.strip_prefix("covered-by-vector:") {
        return file
            .strip_suffix(".json")
            .is_some_and(|stem| !stem.is_empty() && !stem.contains(['/', '\\']));
    }
    matches!(category, "ts-host-only" | "second-pass")
}

#[cfg(test)]
mod tests {
    use super::*;

    const A: &str = "v1|src/tests/handles.test.ts|resolveHandles > mints a handle on start";
    const B: &str = "e2e-http|src/tests/e2e-http/v1-matrix.test.ts|e2e-http v1 lane: sse > echo";
    const RUST_TEST: &str = "agentcat-sdk::handles::resolve_mints_on_start";

    fn ts(keys: &[&str]) -> TsTests {
        let tests: Vec<TsTest> = keys
            .iter()
            .map(|key| {
                let mut parts = key.splitn(3, '|');
                let mut next = || parts.next().unwrap().to_owned();
                TsTest {
                    key: (*key).to_owned(),
                    project: next(),
                    file: next(),
                    title: next(),
                }
            })
            .collect();
        TsTests {
            ts_sha: "9b56e9e920f35f7c37fc2a63ce6520a9ec97edea".to_owned(),
            count: tests.len(),
            tests,
        }
    }

    fn todo(key: &str) -> Entry {
        Entry {
            key: key.to_owned(),
            status: Status::Todo,
            rust: Vec::new(),
            category: None,
            reason: None,
        }
    }

    fn ported(key: &str, rust: &[&str]) -> Entry {
        Entry {
            status: Status::Ported,
            rust: rust.iter().map(|s| (*s).to_owned()).collect(),
            ..todo(key)
        }
    }

    fn not_applicable(key: &str, category: &str, reason: &str) -> Entry {
        Entry {
            status: Status::NotApplicable,
            category: Some(category.to_owned()),
            reason: Some(reason.to_owned()),
            ..todo(key)
        }
    }

    fn manifest(entries: Vec<Entry>) -> Manifest {
        Manifest { tests: entries }
    }

    fn set(items: &[&str]) -> BTreeSet<String> {
        items.iter().map(|s| (*s).to_owned()).collect()
    }

    /// Runs `check` with one known Rust test and one known scenario (`basic`).
    fn run(entries: Vec<Entry>, final_gate: bool) -> Vec<Problem> {
        check(
            &ts(&[A, B]),
            &manifest(entries),
            &set(&[RUST_TEST]),
            &set(&["basic"]),
            final_gate,
        )
    }

    #[test]
    fn clean_manifest_has_no_problems() {
        let entries = vec![
            ported(A, &[RUST_TEST, "harness:basic"]),
            not_applicable(
                B,
                "ts-host-only",
                "the v1 SDK adapter has no Rust counterpart",
            ),
        ];
        assert_eq!(run(entries, true), Vec::new());
    }

    #[test]
    fn todo_is_allowed_without_final() {
        assert_eq!(run(vec![todo(A), todo(B)], false), Vec::new());
    }

    #[test]
    fn unmapped_key_is_reported() {
        assert_eq!(
            run(vec![todo(A)], false),
            vec![Problem::Unmapped(B.to_owned())]
        );
    }

    #[test]
    fn ported_without_rust_is_unmapped() {
        assert_eq!(
            run(vec![ported(A, &[]), todo(B)], false),
            vec![Problem::Unmapped(A.to_owned())]
        );
    }

    #[test]
    fn stale_entry_is_reported() {
        let gone = "v1|src/tests/gone.test.ts|removed > test";
        assert_eq!(
            run(vec![todo(A), todo(B), todo(gone)], false),
            vec![Problem::Stale(gone.to_owned())]
        );
    }

    #[test]
    fn dangling_rust_test_is_reported() {
        let missing = "agentcat-sdk::handles::no_such_test";
        assert_eq!(
            run(vec![ported(A, &[RUST_TEST, missing]), todo(B)], false),
            vec![Problem::DanglingRust {
                key: A.to_owned(),
                test: missing.to_owned(),
            }]
        );
    }

    #[test]
    fn dangling_scenario_is_reported() {
        assert_eq!(
            run(vec![ported(A, &["harness:missing"]), todo(B)], false),
            vec![Problem::DanglingScenario {
                key: A.to_owned(),
                scenario: "missing".to_owned(),
            }]
        );
    }

    #[test]
    fn todo_is_reported_under_final() {
        assert_eq!(
            run(vec![ported(A, &[RUST_TEST]), todo(B)], true),
            vec![Problem::Todo(B.to_owned())]
        );
    }

    #[test]
    fn missing_reason_is_reported() {
        let mut no_reason = not_applicable(B, "second-pass", "");
        assert_eq!(
            run(vec![todo(A), no_reason.clone()], false),
            vec![Problem::MissingReason(B.to_owned())]
        );
        no_reason.reason = None;
        assert_eq!(
            run(vec![todo(A), no_reason], false),
            vec![Problem::MissingReason(B.to_owned())]
        );
        let blank = not_applicable(B, "second-pass", " \t ");
        assert_eq!(
            run(vec![todo(A), blank], false),
            vec![Problem::MissingReason(B.to_owned())]
        );
    }

    #[test]
    fn bad_category_is_reported() {
        assert_eq!(
            run(
                vec![todo(A), not_applicable(B, "out-of-scope", "exporters")],
                false
            ),
            vec![Problem::BadCategory {
                key: B.to_owned(),
                category: "out-of-scope".to_owned(),
            }]
        );
        let mut no_category = not_applicable(B, "", "exporters");
        no_category.category = None;
        assert_eq!(
            run(vec![todo(A), no_category], false),
            vec![Problem::BadCategory {
                key: B.to_owned(),
                category: String::new(),
            }]
        );
    }

    #[test]
    fn duplicate_entry_is_reported() {
        assert_eq!(
            run(vec![todo(A), todo(B), ported(A, &[RUST_TEST])], false),
            vec![Problem::Duplicate(A.to_owned())]
        );
    }

    #[test]
    fn misplaced_field_is_reported() {
        let mut entry = todo(B);
        entry.reason = Some("not yet".to_owned());
        assert_eq!(
            run(vec![todo(A), entry], false),
            vec![Problem::Misplaced {
                key: B.to_owned(),
                field: "reason".to_owned(),
            }]
        );
        let mut entry = not_applicable(B, "second-pass", "later");
        entry.rust = vec![RUST_TEST.to_owned()];
        assert_eq!(
            run(vec![todo(A), entry], false),
            vec![Problem::Misplaced {
                key: B.to_owned(),
                field: "rust".to_owned(),
            }]
        );
        let mut entry = ported(B, &[RUST_TEST]);
        entry.category = Some("second-pass".to_owned());
        assert_eq!(
            run(vec![todo(A), entry], false),
            vec![Problem::Misplaced {
                key: B.to_owned(),
                field: "category".to_owned(),
            }]
        );
    }

    #[test]
    fn every_allowed_category_form_passes() {
        for category in [
            "ts-host-only",
            "second-pass",
            "ruled-divergence:RD-13",
            "ruled-divergence:RD-7",
            "covered-by-vector:constants.json",
            "covered-by-vector:tool-wrap_v2.json",
        ] {
            let entries = vec![todo(A), not_applicable(B, category, "reason")];
            assert_eq!(run(entries, false), Vec::new(), "{category}");
        }
    }

    #[test]
    fn malformed_categories_are_rejected() {
        for category in [
            "",
            "TS-HOST-ONLY",
            "ts-host-only ",
            "ruled-divergence",
            "ruled-divergence:",
            "ruled-divergence:RD-",
            "ruled-divergence:RD-xx",
            "ruled-divergence:RD-1a",
            "ruled-divergence:13",
            "covered-by-vector:",
            "covered-by-vector:.json",
            "covered-by-vector:constants",
            "covered-by-vector:dir/constants.json",
            "covered-by-vector:dir\\constants.json",
        ] {
            let entries = vec![todo(A), not_applicable(B, category, "reason")];
            assert_eq!(
                run(entries, false),
                vec![Problem::BadCategory {
                    key: B.to_owned(),
                    category: category.to_owned(),
                }],
                "{category:?}"
            );
        }
    }

    #[test]
    fn problems_come_back_sorted() {
        let gone = "v1|src/tests/gone.test.ts|removed > test";
        let problems = run(vec![todo(gone), todo(B)], true);
        assert_eq!(
            problems,
            vec![
                Problem::Unmapped(A.to_owned()),
                Problem::Stale(gone.to_owned()),
                Problem::Todo(B.to_owned()),
            ]
        );
    }

    #[test]
    fn manifest_parses_the_documented_schema() {
        let text = r#"
# comment
[[test]]
key = "v1|src/tests/handles.test.ts|resolveHandles > mints a handle on start"
status = "ported"
rust = ["agentcat-sdk::handles::resolve_mints_on_start", "harness:basic"]

[[test]]
key = "v1|src/tests/a.test.ts|quotes \"x\" and a backslash \\t"
status = "n/a"
category = "ts-host-only"
reason = "TS host only"

[[test]]
key = "v2|src/tests/v2/b.test.ts|b"
status = "todo"
"#;
        let parsed = Manifest::from_toml(text).unwrap();
        let mut na = not_applicable(
            "v1|src/tests/a.test.ts|quotes \"x\" and a backslash \\t",
            "ts-host-only",
            "TS host only",
        );
        na.rust = Vec::new();
        assert_eq!(
            parsed,
            manifest(vec![
                ported(A, &[RUST_TEST, "harness:basic"]),
                na,
                todo("v2|src/tests/v2/b.test.ts|b"),
            ])
        );
        assert_eq!(Manifest::from_toml("").unwrap(), Manifest::default());
    }

    #[test]
    fn manifest_rejects_unknown_fields_and_statuses() {
        let typo = "[[test]]\nkey = \"k\"\nstatus = \"n/a\"\nreasons = \"x\"\n";
        assert!(Manifest::from_toml(typo).unwrap_err().contains("reasons"));
        let status = "[[test]]\nkey = \"k\"\nstatus = \"done\"\n";
        assert!(Manifest::from_toml(status).unwrap_err().contains("done"));
    }

    #[test]
    fn ts_tests_parse_and_must_be_consistent() {
        let good = r#"{"ts_sha": "abc", "count": 1, "tests": [
            {"key": "v1|f.test.ts|a > b", "project": "v1", "file": "f.test.ts", "title": "a > b"}]}"#;
        let parsed = TsTests::from_json(good).unwrap();
        assert_eq!(parsed.tests[0].title, "a > b");

        let bad_count = good.replace("\"count\": 1", "\"count\": 2");
        assert!(
            TsTests::from_json(&bad_count)
                .unwrap_err()
                .contains("count")
        );

        let bad_key = good.replace(
            "\"key\": \"v1|f.test.ts|a > b\"",
            "\"key\": \"v1|f.test.ts|a\"",
        );
        assert!(
            TsTests::from_json(&bad_key)
                .unwrap_err()
                .contains("v1|f.test.ts|a")
        );

        let one =
            r#"{"key": "v1|f.test.ts|a", "project": "v1", "file": "f.test.ts", "title": "a"}"#;
        let duplicate = format!(r#"{{"ts_sha": "abc", "count": 2, "tests": [{one}, {one}]}}"#);
        assert!(
            TsTests::from_json(&duplicate)
                .unwrap_err()
                .contains("duplicate")
        );
    }

    /// `testdata/nextest-list.json` is real `cargo nextest list --workspace --all-features
    /// --message-format json` output (nextest 0.9.148), pretty-printed, with fewer test cases and
    /// shorter paths.
    #[test]
    fn rust_test_names_from_captured_nextest_list() {
        let names = rust_test_names(include_str!("testdata/nextest-list.json")).unwrap();
        assert_eq!(
            names,
            set(&[
                "agentcat-sdk::oracle_smoke::a_panic_while_holding_the_oracle_does_not_break_the_next_call",
                "agentcat-sdk::oracle_smoke::an_unknown_function_is_an_err_and_the_oracle_keeps_serving",
                "agentcat-sdk::oracle_smoke::js_drops_the_fraction_of_whole_floats",
                "agentcat-sdk::oracle_smoke::js_stringify_of_strings_round_trips",
                "agentcat-sdk::oracle_smoke::js_undefined_is_none",
                "agentcat-sdk::oracle_smoke::support::oracle::tests::an_err_reply_with_a_wrong_or_null_id_is_a_protocol_error",
                "agentcat-sdk::oracle_smoke::support::oracle::tests::an_err_reply_with_the_right_id_is_the_error",
                "agentcat-sdk::oracle_smoke::support::oracle::tests::ok_and_undefined_replies_with_a_wrong_id_are_protocol_errors",
                "xtask::bin/xtask::parity::tests::bad_category_is_reported",
                "xtask::bin/xtask::parity::tests::clean_manifest_has_no_problems",
            ])
        );
    }

    #[test]
    fn rust_test_names_rejects_other_json() {
        assert!(rust_test_names("{}").is_err());
        assert!(rust_test_names("not json").is_err());
    }

    #[test]
    fn missing_scenario_dir_is_an_empty_set() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("no-such-scenarios-dir");
        assert_eq!(scenario_names(&dir).unwrap(), BTreeSet::new());
    }

    #[test]
    fn scenario_names_are_json_file_stems() {
        let dir = std::env::temp_dir().join(format!("xtask-scenarios-{}", std::process::id()));
        fs::create_dir_all(dir.join("nested.json")).unwrap();
        fs::write(dir.join("basic.json"), "{}").unwrap();
        fs::write(dir.join("identify.json"), "{}").unwrap();
        fs::write(dir.join("notes.md"), "").unwrap();
        let names = scenario_names(&dir);
        fs::remove_dir_all(&dir).unwrap();
        assert_eq!(names.unwrap(), set(&["basic", "identify"]));
    }
}
